import React from "react";
import { Row, Col } from "react-bootstrap";

export const Newsletter = () => {
  return (
    <>
      <section className="cta-full">
        <div className="cta-wrapper">
          <Row className="align-items-center m-0">

            <Col lg={8} className="p-0">
              <h2 className="cta-title">
                Let’s Turn Ideas Into Reality ✨
              </h2>
              <p className="cta-text">
                Passionate about building modern and responsive web experiences.
                Open to internships, freelance collaborations, and full-time opportunities.
                Let’s connect and create something impactful together.
              </p>
            </Col>

            <Col lg={4} className="text-lg-end text-center p-0 mt-4 mt-lg-0">
              <a href="#connect" className="cta-btn-new">
                Let’s Connect
              </a>
            </Col>

          </Row>
        </div>
      </section>

      <style>{`

        /* FULL WIDTH SECTION */
        .cta-full {
          width: 100%;
          padding: 100px 8%;
          background: linear-gradient(90deg, #7b2ff7, #f107a3);
        }

        .cta-wrapper {
          background: rgba(0, 0, 0, 0.25);
          padding: 60px;
          border-radius: 25px;
          backdrop-filter: blur(15px);
          box-shadow: 0 25px 60px rgba(0,0,0,0.5);
          transition: 0.4s ease;
        }

        .cta-wrapper:hover {
          transform: translateY(-10px);
          box-shadow: 0 35px 70px rgba(0,0,0,0.7);
        }

        .cta-title {
          font-size: 40px;
          font-weight: 800;
          color: #ffffff;
          letter-spacing: 1px;
          margin-bottom: 20px;
        }

        .cta-text {
          font-size: 17px;
          color: #f1f1f1;
          line-height: 1.8;
          max-width: 650px;
        }

        .cta-btn-new {
          display: inline-block;
          padding: 16px 50px;
          border-radius: 50px;
          font-size: 17px;
          font-weight: 600;
          text-decoration: none;
          background: #ffffff;
          color: #7b2ff7;
          transition: all 0.4s ease;
          box-shadow: 0 10px 25px rgba(0,0,0,0.4);
        }

        .cta-btn-new:hover {
          background: #000;
          color: #fff;
          transform: scale(1.1);
          box-shadow: 0 20px 40px rgba(0,0,0,0.6);
        }

        @media (max-width: 768px) {
          .cta-title {
            font-size: 28px;
          }
          .cta-wrapper {
            padding: 40px 25px;
          }
        }

      `}</style>
    </>
  );
};
